import {readFileSync} from 'node:fs';
import assert from 'node:assert/strict';
import {parseStatus} from './status.mjs';
import {parseHuman} from './human.mjs';
const file=process.argv[2];const text=readFileSync(file,'utf8');
const parsed=parseStatus(text,'WPF-DASHBOARD-ACCESS01');
const fields=Object.fromEntries(text.split('\n').filter(line=>line.startsWith('|')).map(line=>line.split('|').slice(1,-1).map(x=>x.trim())).filter(row=>row.length===2).map(([key,value])=>[key.replace(/\s+/g,'').toLowerCase(),value]));
const direct=parseHuman(pattern=>Object.entries(fields).find(([key])=>pattern.test(key))?.[1]??'');
assert.deepEqual(parsed.errors,[]);assert.equal(parsed.human.complete,true);assert.equal(parsed.human.blocker.state,'none');assert.equal(direct.complete,true);assert.deepEqual(direct,parsed.human);assert.equal(parsed.implementation.target,'53723697a796a1346164c4cddc82ab99baf168ea');
console.log(JSON.stringify({state:'PASSED_METADATA_ONLY',taskId:parsed.taskId,errors:parsed.errors,human:parsed.human,directParseHuman:direct,implementation:parsed.implementation,timing:parsed.timing,productTest:false}));
